if (points.size() < 3) {
    return points;
}

// Find the bottom-most point (and left-most in case of tie)
auto it = std::min_element(points.begin(), points.end(), [](const Point_2& a, const Point_2& b) {
    return (a.y() < b.y()) || (a.y() == b.y() && a.x() < b.x());
});
Point_2 p0 = *it;
std::vector<Point_2> hull;
hull.push_back(p0);

// Sort the remaining points by polar angle with respect to p0
points.erase(it);
std::sort(points.begin(), points.end(), [&p0](const Point_2& a, const Point_2& b) {
    // Cross product to determine orientation
    auto cross = (a.y() - p0.y()) * (b.x() - p0.x()) - (a.x() - p0.x()) * (b.y() - p0.y());
    if (cross == 0) {
        // Collinear points: keep the farthest
        return CGAL::squared_distance(p0, a) < CGAL::squared_distance(p0, b);
    }
    return cross > 0;
});

// Graham scan
for (const auto& p : points) {
    // Remove points that make a clockwise turn
    while (hull.size() > 1) {
        auto last = hull.back(); hull.pop_back();
        auto cross = CGAL::cross_product(last - hull.back(), p - last);
        if (cross > 0) {
            hull.push_back(last);
            break;
        }
    }
    hull.push_back(p);
}

return hull;

